// Rasterises the brand SVGs into the base64 PNG constants under lib/email-assets/.
// Usage: npx tsx scripts/make-email-assets.ts
// Re-run after editing a mark in design/reference/; commit the generated files.
// The PNGs are rendered at 2x their display size so they stay crisp on retina
// screens, on a transparent background so they sit on any email ground.
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import sharp from "sharp";

const ROOT = join(import.meta.dirname, "..");
const SOURCE_DIR = join(ROOT, "design", "reference");
const OUT_DIR = join(ROOT, "lib", "email-assets");
/** The SVGs are drawn on a 24-unit viewBox at 72 dpi. */
const SVG_UNITS = 24;

interface Spec {
  /** Export name and file stem. */
  name: string;
  file: string;
  contentId: string;
  /** Rendered pixel size (square). */
  size: number;
}

const SPECS: Spec[] = [
  { name: "heart", file: "heart-solid.svg", contentId: "brand-heart", size: 88 },
  { name: "heartStitched", file: "heart-stitched.svg", contentId: "brand-heart-stitched", size: 80 },
  { name: "badgePlay", file: "badge-play.svg", contentId: "brand-badge-play", size: 112 },
  { name: "badgeAudio", file: "badge-audio.svg", contentId: "brand-badge-audio", size: 112 },
  { name: "badgeVideo", file: "badge-video.svg", contentId: "brand-badge-video", size: 112 },
  { name: "badgePhoto", file: "badge-photo.svg", contentId: "brand-badge-photo", size: 112 },
];

/** Larger play badge for compositing onto video posters (never attached by itself). */
const PLAY_COMPOSITE_SIZE = 160;

async function render(file: string, size: number): Promise<{ base64: string; width: number; height: number }> {
  const svg = readFileSync(join(SOURCE_DIR, file));
  const density = (72 * size) / SVG_UNITS;
  const { data, info } = await sharp(svg, { density }).png({ compressionLevel: 9 }).toBuffer({ resolveWithObject: true });
  if (info.width !== size || info.height !== size) {
    throw new Error(`${file}: rendered ${info.width}x${info.height}, expected ${size}x${size}`);
  }
  return { base64: data.toString("base64"), width: info.width, height: info.height };
}

function moduleSource(exportName: string, contentId: string, rendered: { base64: string; width: number; height: number }): string {
  return [
    "// Generated by scripts/make-email-assets.ts from design/reference/; do not edit by hand.",
    `export const ${exportName} = {`,
    `  contentId: ${JSON.stringify(contentId)},`,
    '  contentType: "image/png",',
    `  width: ${rendered.width},`,
    `  height: ${rendered.height},`,
    `  contentBase64: ${JSON.stringify(rendered.base64)},`,
    "} as const;",
    "",
  ].join("\n");
}

function constName(name: string): string {
  return name.replaceAll(/([a-z])([A-Z])/g, "$1_$2").toUpperCase();
}

async function main(): Promise<void> {
  mkdirSync(OUT_DIR, { recursive: true });
  const exports: string[] = [];
  for (const spec of SPECS) {
    const rendered = await render(spec.file, spec.size);
    const exportName = constName(spec.name);
    writeFileSync(join(OUT_DIR, `${spec.name}.ts`), moduleSource(exportName, spec.contentId, rendered));
    exports.push(`import { ${exportName} } from "./${spec.name}";`);
    console.log(`${spec.file} → ${spec.name}.ts (${spec.size}px, ${Math.round(rendered.base64.length * 0.75)} bytes)`);
  }
  const composite = await render("badge-play.svg", PLAY_COMPOSITE_SIZE);
  writeFileSync(join(OUT_DIR, "playBadgeComposite.ts"), moduleSource("PLAY_BADGE_COMPOSITE", "brand-badge-play-composite", composite));
  console.log(`badge-play.svg → playBadgeComposite.ts (${PLAY_COMPOSITE_SIZE}px)`);

  const index = [
    "// Generated by scripts/make-email-assets.ts; do not edit by hand.",
    ...exports,
    "",
    "export { PLAY_BADGE_COMPOSITE } from \"./playBadgeComposite\";",
    "",
    "/** A brand mark carried inline in an email, referenced as `cid:<contentId>`. */",
    "export interface EmailAsset {",
    "  contentId: string;",
    '  contentType: "image/png";',
    "  width: number;",
    "  height: number;",
    "  contentBase64: string;",
    "}",
    "",
    "export const EMAIL_ASSETS = {",
    ...SPECS.map((spec) => `  ${spec.name}: ${constName(spec.name)},`),
    "} as const satisfies Record<string, EmailAsset>;",
    "",
  ].join("\n");
  writeFileSync(join(OUT_DIR, "index.ts"), index);
}

main().catch((error: unknown) => {
  console.error(error instanceof Error ? error.message : error);
  process.exitCode = 1;
});
